      fr: ["Fondation : 1995", "Superficie : 250 hectares", "Nombre d'animaux : plus de 1 000", "Distance de Phnom Penh : 40 km", "Nombre d'éléphants : env. 10", "Nombre annuel de visiteurs : environ 100 000"],
