      hu: ["Az UNESCO Tonle Sap Bioszféra-rezervátum része", "Körülbelül 31 000 hektáros terület", "A foltoscsőrű pelikánok fő fészkelőhelye", "Legjobb látogatási időszak: decembertől márciusig", "Több mint 150 madárfaj otthona", "A Wildlife Conservation Society felügyeli"],
