      fr: ["Superficie : 50 km²", "Couples nicheurs de tantale blanc : plus de 2 000", "Distance de Battambang : 90 km", "Hauteur des arbres : jusqu'à 30 m", "Nombre d'espèces d'oiseaux : plus de 100", "Trajet en bateau : env. 2 heures"],
