      es: ["Se encuentra al pie del Kbal Spean.", "Se centra en primates, pangolines y tortugas raras.", "Muchos de los animales fueron rescatados del comercio ilegal de fauna silvestre."],
      pt: ["Situado no sopé do Kbal Spean.", "Foca-se em primatas, pangolins e tartarugas raras.", "Muitos dos animais foram resgatados do comércio ilegal de vida selvagem."],
