      en: ["Cambodia's first elephant sanctuary (est. 2006)", "Run by the NGO ELIE in Mondulkiri", "Maintains a strict no-riding and no-bathing policy", "Works in partnership with the Bunong people", "Focuses on the rehabilitation of working elephants", "Funds healthcare and education for local villages"],
