      pt: "Um dos melhores locais no Camboja para observar os raros golfinhos-do-irrawaddy em estado selvagem no Mekong.",
      fr: "L'un des meilleurs endroits au Cambodge pour observer les rares dauphins de l'Irrawaddy en liberté dans le Mékong.",
