      en: "An eco-friendly pepper farm in Kep that gives visitors insight into traditional pepper cultivation.",
      es: "Una granja de pimienta ecológica en Kep que ofrece a los visitantes una visión del cultivo tradicional de la pimienta.",
      pt: "Uma fazenda de pimenta ecológica em Kep que oferece aos visitantes uma visão sobre o cultivo tradicional de pimenta.",
