      es: "Una reserva natural reconocida internacionalmente en el norte de Camboya, famosa por sus esfuerzos de conservación del ibis.",
      pt: "Uma reserva natural reconhecida internacionalmente no norte do Camboja, famosa pelos seus esforços de conservação do íbis.",
