      hu: ["A Pursat narancs héja érett állapotban is zöld színű marad.", "Battambang tartomány Kambodzsa legfontosabb citrus-régiója.", "A talaj tápanyagtartalmát a Tonle Sap-tó üledékei adják.", "A főszezon és a betakarítás októbertől februárig tart.", "A Kamping Puoy-víztározó kulcsfontosságú az öntözéshez.", "A helyi gazdák egyre több biogazdálkodási módszert alkalmaznak."],
      ro: ["Portocala de Pursat își păstrează culoarea verde a cojii chiar și coaptă.", "Provincia Battambang asigură cea mai mare parte a producției de citrice.", "Solul fertil este rezultatul depunerilor aluvionare ale lacului Tonle Sap.", "Recoltarea principală are loc în intervalul octombrie - februarie.", "Rezervorul Kamping Puoy este o sursă vitală de apă pentru irigații.", "Fermierii locali pun tot mai mult accent pe certificarea organică."],
