      es: ["Las plantaciones abarcan 50 hectáreas de tierra.", "La época de cosecha es de noviembre a febrero.", "Se producen 100 toneladas de naranjas al año.", "Una naranja pesa una media de 200 gramos.", "Existen más de 20 variedades de naranjas.", "La primera plantación fue establecida en 1985."],
      pt: ["Os pomares abrangem 50 hectares de terra.", "A época da colheita é de novembro a fevereiro.", "São produzidas 100 toneladas de laranjas por ano.", "Uma laranja pesa em média 200 gramas.", "Existem mais de 20 variedades de laranjas.", "A primeira plantação foi estabelecida em 1985."],
      fr: ["Les vergers couvrent 50 hectares de terre.", "La période de récolte s'étend de novembre à février.", "100 tonnes d'oranges sont produites chaque année.", "Une orange pèse en moyenne 200 grammes.", "Il existe plus de 20 variétés d'oranges.", "Le premier verger a été créé en 1985."],
